
const WORDS=[{"id": 0, "w": "化妆", "p": "huàzhuāng", "t": "动词", "m": "trang điểm, hóa trang", "coll": "化妆表演、学会化妆", "s": "演出开始之前，演员们正在后台化妆。"}, {"id": 1, "w": "屑", "p": "xiè", "t": "名词", "m": "vụn, mảnh vụn", "coll": "木屑、纸屑", "s": "木工师傅把地上的木屑清理干净。"}, {"id": 2, "w": "抢劫", "p": "qiǎngjié", "t": "动词", "m": "cướp giật, ăn cướp", "coll": "抢劫案件、遭遇抢劫", "s": "警方接到报案后，立即开始调查这起抢劫案件。"}, {"id": 3, "w": "痕迹", "p": "hénjì", "t": "名词", "m": "vết tích, dấu vết", "coll": "留下痕迹、寻找痕迹", "s": "岁月在这座老房子的墙上留下了明显的痕迹。"}, {"id": 4, "w": "停顿", "p": "tíngdùn", "t": "动词", "m": "tạm dừng, ngừng lại", "coll": "稍作停顿、停顿片刻", "s": "讲到这里，他稍作停顿，看了看台下的听众。"}, {"id": 5, "w": "嫌疑", "p": "xiányí", "t": "名词", "m": "sự tình nghi, sự nghi ngờ", "coll": "排除嫌疑、有嫌疑", "s": "经过认真核实，调查人员排除了他的嫌疑。"}, {"id": 6, "w": "线索", "p": "xiànsuǒ", "t": "名词", "m": "đầu mối, manh mối", "coll": "重要线索、提供线索", "s": "一位热心居民向警方提供了重要线索。"}, {"id": 7, "w": "歹徒", "p": "dǎitú", "t": "名词", "m": "tên vô lại, tên côn đồ", "coll": "抓获歹徒、持刀歹徒", "s": "在群众的协助下，警方很快抓获了逃跑的歹徒。"}, {"id": 8, "w": "恐惧", "p": "kǒngjù", "t": "形容词", "m": "sợ hãi, hoảng sợ", "coll": "感到恐惧、克服恐惧", "s": "第一次站上舞台时，她努力克服心中的恐惧。"}, {"id": 9, "w": "铜", "p": "tóng", "t": "名词", "m": "đồng (ký hiệu Cu)", "coll": "铜制品、铜器", "s": "这件古代器物是用铜制作而成的。"}, {"id": 10, "w": "框架", "p": "kuàngjià", "t": "名词", "m": "khung (ảnh, xe...), sườn (tàu, nhà...)", "coll": "基本框架、框架结构", "s": "写文章之前，他先列出了整体框架。"}, {"id": 11, "w": "残留", "p": "cánliú", "t": "动词", "m": "còn sót lại, còn lại", "coll": "残留痕迹、残留物", "s": "清洗以后，杯子里仍然残留着一点茶的香味。"}, {"id": 12, "w": "刑事", "p": "xíngshì", "t": "形容词", "m": "hình sự", "coll": "刑事案件、刑事调查", "s": "这本书讲述了几起刑事案件的调查过程。"}, {"id": 13, "w": "监狱", "p": "jiānyù", "t": "名词", "m": "nhà tù, nhà giam", "coll": "监狱管理、走出监狱", "s": "这部纪录片介绍了监狱里的教育工作。"}, {"id": 14, "w": "慎重", "p": "shènzhòng", "t": "形容词", "m": "thận trọng, cẩn thận", "coll": "慎重考虑、态度慎重", "s": "作出重要决定之前，我们需要慎重考虑可能的后果。"}, {"id": 15, "w": "麻痹", "p": "mábì", "t": "动词／形容词", "m": "tê liệt; lơ là, mất cảnh giác", "coll": "麻痹大意、不能麻痹", "s": "即使工作已经接近结束，也不能麻痹大意。"}, {"id": 16, "w": "失误", "p": "shīwù", "t": "名词／动词", "m": "sai sót, sơ suất; mắc sai sót", "coll": "工作失误、避免失误", "s": "他主动承认了工作中的失误，并及时进行了改正。"}, {"id": 17, "w": "考验", "p": "kǎoyàn", "t": "动词", "m": "khảo nghiệm, thử thách", "coll": "经受考验、严峻的考验", "s": "这段艰难的经历考验了团队的耐心和意志。"}, {"id": 18, "w": "检验", "p": "jiǎnyàn", "t": "动词", "m": "kiểm tra, kiểm nghiệm", "coll": "检验质量、接受检验", "s": "产品出厂之前，必须经过严格的质量检验。"}, {"id": 19, "w": "查获", "p": "cháhuò", "t": "动词", "m": "theo dõi và bắt được, tra xét và thu được", "coll": "查获赃物、查获物品", "s": "警方在调查中查获了多件被盗文物。"}, {"id": 20, "w": "制裁", "p": "zhìcái", "t": "动词", "m": "trừng phạt, trừng trị", "coll": "受到制裁、依法制裁", "s": "小说中的反派最终因自己的罪行受到了制裁。"}, {"id": 21, "w": "公安局", "p": "gōng'ānjú", "t": "名词", "m": "cục cảnh sát", "coll": "市公安局、到公安局报案", "s": "丢失重要证件后，他到公安局咨询了相关处理办法。"}, {"id": 22, "w": "情报", "p": "qíngbào", "t": "名词", "m": "tin tức, tình báo", "coll": "收集情报、重要情报", "s": "工作人员认真核实了这份情报的来源。"}, {"id": 23, "w": "毒品", "p": "dúpǐn", "t": "名词", "m": "thuốc phiện, ma túy", "coll": "远离毒品、毒品危害", "s": "学校通过专题讲座，帮助学生认识毒品的危害。"}, {"id": 24, "w": "带领", "p": "dàilǐng", "t": "动词", "m": "dẫn dắt, lãnh đạo, chỉ huy", "coll": "带领团队、带领学生", "s": "老师带领学生参观博物馆，了解当地的历史。"}, {"id": 25, "w": "沉着", "p": "chénzhuó", "t": "形容词", "m": "bình tĩnh, điềm tĩnh", "coll": "沉着冷静、沉着应对", "s": "面对突发情况，她依然沉着冷静，有条不紊地安排工作。"}, {"id": 26, "w": "暂且", "p": "zànqiě", "t": "副词", "m": "tạm thời", "coll": "暂且不谈、暂且放下", "s": "这个问题我们暂且不谈，先把眼前的工作完成好。"}, {"id": 27, "w": "部署", "p": "bùshǔ", "t": "动词", "m": "sắp xếp, bố trí", "coll": "部署工作、作出部署", "s": "会议结束后，负责人对下一阶段的工作作出了部署。"}, {"id": 28, "w": "埋伏", "p": "máifú", "t": "动词", "m": "phục kích, mai phục, nằm rình, nằm chờ", "coll": "设下埋伏、提前埋伏", "s": "这部电影描写了战士们在山谷中埋伏等待的场景。"}, {"id": 29, "w": "布置", "p": "bùzhì", "t": "动词", "m": "sắp xếp, tổ chức, bố trí", "coll": "布置教室、布置任务", "s": "开学之前，同学们一起布置教室。"}, {"id": 30, "w": "反抗", "p": "fǎnkàng", "t": "动词", "m": "phản kháng, chống lại", "coll": "进行反抗、反抗压迫", "s": "故事中的村民团结起来，反抗不公正的压迫。"}, {"id": 31, "w": "逮捕", "p": "dàibǔ", "t": "动词", "m": "bắt giữ", "coll": "依法逮捕、遭到逮捕", "s": "这部小说的结尾，犯罪嫌疑人终于被逮捕。"}, {"id": 32, "w": "非法", "p": "fēifǎ", "t": "形容词", "m": "không hợp pháp, trái luật", "coll": "非法行为、非法经营", "s": "这篇报道揭露了一些企业非法经营的问题。"}, {"id": 33, "w": "贩卖", "p": "fànmài", "t": "动词", "m": "mua đi bán lại, buôn bán (thường dùng với hàng cấm trong ngữ cảnh bài)", "coll": "贩卖商品、贩卖毒品", "s": "这部电影讲述了警方打击贩卖毒品行为的故事。"}, {"id": 34, "w": "平面", "p": "píngmiàn", "t": "名词", "m": "mặt bằng, mặt phẳng", "coll": "平面图、平面设计", "s": "参观之前，她先看了博物馆的平面图。"}, {"id": 35, "w": "平行", "p": "píngxíng", "t": "形容词／动词", "m": "song song", "coll": "相互平行、平行线", "s": "在这幅图中，两条直线始终保持平行。"}, {"id": 36, "w": "并列", "p": "bìngliè", "t": "动词", "m": "đặt song song hàng", "coll": "并列第一、并列关系", "s": "两位选手成绩相同，并列第一。"}, {"id": 37, "w": "交叉", "p": "jiāochā", "t": "动词", "m": "đan chéo, đan xen, chồng chéo", "coll": "道路交叉、交叉检查", "s": "两条道路在广场前交叉，形成一个繁忙的路口。"}, {"id": 38, "w": "包袱", "p": "bāofu", "t": "名词", "m": "bọc đồ; gánh nặng, điều đè nặng tâm lý", "coll": "放下包袱、思想包袱", "s": "老师鼓励他放下思想包袱，勇敢尝试新的学习方法。"}, {"id": 39, "w": "胆怯", "p": "dǎnqiè", "t": "形容词", "m": "nhút nhát, sợ sệt", "coll": "感到胆怯、克服胆怯", "s": "第一次独自出远门，他心里有些胆怯。"}, {"id": 40, "w": "哄", "p": "hǒng", "t": "动词", "m": "dỗ dành, dỗ ngọt, vỗ về, đánh lừa", "coll": "哄孩子、哄人开心", "s": "妈妈轻声哄着孩子，让他慢慢安静下来。"}, {"id": 41, "w": "信赖", "p": "xìnlài", "t": "动词", "m": "tin cậy", "coll": "值得信赖、互相信赖", "s": "长期的合作使他们成为彼此信赖的伙伴。"}, {"id": 42, "w": "忠诚", "p": "zhōngchéng", "t": "形容词", "m": "trung thành", "coll": "忠诚可靠、保持忠诚", "s": "他以认真负责的态度，表达了对这份事业的忠诚。"}, {"id": 43, "w": "舌头", "p": "shétou", "t": "名词", "m": "cái lưỡi", "coll": "伸出舌头、舌头发麻", "s": "小狗伸出舌头，在树荫下轻轻地喘着气。"}, {"id": 44, "w": "舔", "p": "tiǎn", "t": "动词", "m": "liếm", "coll": "舔手、舔干净", "s": "小猫低下头，慢慢地舔着爪子。"}, {"id": 45, "w": "空隙", "p": "kòngxì", "t": "名词", "m": "khe hở, khoảng trống", "coll": "留出空隙、狭小的空隙", "s": "摆放书籍时，他在两排书之间留出了一点空隙。"}, {"id": 46, "w": "扒", "p": "bā", "t": "动词", "m": "cào bới, moi, đẩy sang một bên", "coll": "扒土、扒开草丛", "s": "小狗用前爪扒着地上的土，好像发现了什么东西。"}, {"id": 47, "w": "垫", "p": "diàn", "t": "动词／名词", "m": "lót, kê, đệm; tấm lót, đệm", "coll": "垫一张纸、软垫", "s": "为了保护桌面，她在杯子下面垫了一张纸。"}, {"id": 48, "w": "叼", "p": "diāo", "t": "动词", "m": "ngậm, tha", "coll": "叼着树枝、叼走食物", "s": "小狗叼着一根树枝，高兴地跑了回来。"}, {"id": 49, "w": "粉末", "p": "fěnmò", "t": "名词", "m": "bột, phấn", "coll": "白色粉末、研成粉末", "s": "工人把材料研成粉末，装进了标有名称的容器。"}, {"id": 50, "w": "口腔", "p": "kǒuqiāng", "t": "名词", "m": "khoang miệng", "coll": "口腔清洁、口腔检查", "s": "这次活动介绍了口腔清洁方面的基本知识。"}, {"id": 51, "w": "岗位", "p": "gǎngwèi", "t": "名词", "m": "cương vị, vị trí công tác, chức vụ", "coll": "工作岗位、坚守岗位", "s": "节日期间，许多工作人员仍然坚守自己的岗位。"}, {"id": 52, "w": "战役", "p": "zhànyì", "t": "名词", "m": "chiến dịch", "coll": "重要战役、战役经过", "s": "历史老师用地图讲解了这场战役的经过。"}, {"id": 53, "w": "光辉", "p": "guānghuī", "t": "名词／形容词", "m": "ánh sáng rực rỡ; huy hoàng, vẻ vang", "coll": "光辉历程、光辉形象", "s": "这本纪念册记录了学校发展的光辉历程。"}, {"id": 54, "w": "思念", "p": "sīniàn", "t": "动词", "m": "nhớ nhung, mong nhớ", "coll": "思念故乡、深深思念", "s": "离家求学以后，她常常思念故乡的亲人。"}];
